	{8'h00,8'h00,8'h00,8'h00,8'h00,8'h00,8'h00,8'h00,8'h00,8'h00,8'h00,8'h00,8'h00,8'h00,8'h00,8'h00,8'h00,8'h00,8'h00,8'h00,8'h00,8'h00,8'h49,8'hd1,8'hd1,8'hd1,8'h92,8'h52,8'h93,8'hdb,8'hdb,8'hdb},
	{8'h00,8'h00,8'h00,8'h00,8'h00,8'h00,8'h00,8'h00,8'h00,8'h00,8'h00,8'h00,8'h00,8'h00,8'h00,8'h00,8'h00,8'h00,8'h00,8'h00,8'h00,8'h00,8'h00,8'h00,8'hd1,8'h92,8'h52,8'h92,8'h9b,8'h9b,8'hdb,8'hdb},
	{8'h00,8'h00,8'h00,8'h00,8'h00,8'h00,8'h00,8'h00,8'h00,8'h00,8'h00,8'h00,8'h00,8'h00,8'h00,8'h00,8'h00,8'h00,8'h00,8'h00,8'h00,8'h00,8'h00,8'h00,8'h00,8'h49,8'h52,8'h92,8'h93,8'h9b,8'h9b,8'hdb}}};
// pipeline (ff) to get the pixel color from the array 	 

//==----------------------------------------------------------------------------------------------------------------=
always_ff@(posedge clk or negedge resetN)
begin
	if(!resetN) begin
		RGBout <=	8'h00;
		flag=0;
		x=0;
	end
	else begin
		RGBout <= TRANSPARENT_ENCODING ; // default 
		if(player_angle) begin
			flag=1;
			up=1;
		end
		if(flag==1) begin
			if(SOF) begin
				if(up)
					x+=5;
				else if (x>=5)
					x-=5;
			end
			if(x>=70)
				up=0;
			if(x<=5 & up==0 & !player_angle)
				flag=0;
		end
		
		if(x>=60)
			HitMode=2'd3;
		
		else if(x<=10)
			HitMode=2'd0;
			
		else if(x<= 45 & x>=28)
			HitMode=2'd2;
			
		else if (x<=28 & x>=10)
			HitMode=2'd1;
		
		if ((InsideRectangle == 1'b1 )		& 	// only if inside the external bracket 
		   (MazeBiMapMask[offsetY[8:5] ][offsetX[8:5]] == 1'b1 )) begin // take bits 5,6,7,8,9,10 from address to select  position in the maze    
				if(HitMode==2'd0)
						RGBout <= object_colors[2][offsetY[4:0]][offsetX[4:0]] ;
				else if(HitMode==2'd3)
						RGBout <= object_colors[2][offsetX[4:0]][offsetY[4:0]] ;
				else if(HitMode==2'd1)
						RGBout <= object_colors[1][offsetY[4:0]][offsetX[4:0]] ;
				else if(HitMode==2'd2)
						RGBout <= object_colors[0][offsetY[4:0]][offsetX[4:0]] ;
				end
		end 
end

//==----------------------------------------------------------------------------------------------------------------=
// decide if to draw the pixel or not 
assign drawingRequest = (RGBout != TRANSPARENT_ENCODING ) ? 1'b1 : 1'b0 ; // get optional transparent command from the bitmpap   
endmodule

